/**
 * @method
 * @name historyChgName
 * @description desc
 * @param {string} rep_isu_srt_cd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.historyChgName = function(rep_isu_srt_cd) {
    var chgList;
    var strPageURL = "/PersonInfo.do?method=historyChgName&comCode=" + rep_isu_srt_cd;
    var strOptions = "width=450, height=220, toolbar=no, location=no, menubar=no, scrollbars=yes, status=yes, resizable=no";
    chgList = window.open(strPageURL, "chgList", strOptions);
    chgList.focus();
};
/**
 * @method
 * @name openNews
 * @description desc
 * @param {string} comName desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.openNews = function(comName) {
    var _previewWindow;
    _previewWindow = window.open('', 'news', 'width=785, height=700, toolbar=no, location=no, menubar=no, scrollbars=yes, status=yes, resizable=yes');
    //_previewWindow.opener=self;
    _previewWindow.focus();
    var f = document.frmNews;
    f.target = "news";
    f.comName.setValue(encodeURIComponent(comName));
    f.action = '/dsclmgt/JLDSTF37033.jsp';
    f.submit();
};
/**
 * @method
 * @name fileDownLoad
 * @description desc
 * @param {string} file_id desc
 * @param {string} attach_seq desc
 * @param {string} attach_filenm desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fileDownLoad = function(file_id, attach_seq, attach_filenm) {
    document.fileDownForm.action = '/filedownload.do';
    document.fileDownForm.gubun.setValue("17");
    document.fileDownForm.file_id.setValue(file_id);
    document.fileDownForm.attach_seq.setValue(attach_seq);
    document.fileDownForm.submit();
    screnProcsTpCd = '08';
    scwin.fn_connStratLog(js_emp_no, screnId, screnProcsTpCd, indCond, attach_filenm);
};
/**
 * @method
 * @name fileDownLoad2
 * @description desc
 * @param {string} file_id desc
 * @param {string} attach_data_seq desc
 * @param {string} attach_seq desc
 * @param {string} attach_filenm desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fileDownLoad2 = function(file_id, attach_data_seq, attach_seq, attach_filenm) {
    document.fileDownForm.action = '/filedownload.do';
    document.fileDownForm.gubun.setValue("18");
    document.fileDownForm.file_id.setValue(file_id);
    document.fileDownForm.attach_data_seq.setValue(attach_data_seq);
    document.fileDownForm.attach_seq.setValue(attach_seq);
    document.fileDownForm.submit();
    screnProcsTpCd = '08';
    scwin.fn_connStratLog(js_emp_no, screnId, screnProcsTpCd, indCond, attach_filenm);
};
/**
 * @method
 * @name openDisclosureView
 * @description desc
 * @param {string} severGubun desc
 * @param {string} accpt_no desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.openDisclosureView = function(severGubun, accpt_no) {
    var sUrl = "https://staff.krx.co.kr";
    if (severGubun != '') {
        if (severGubun == "local" || severGubun == "dev") {
            //sUrl = "https://10.47.120.120:8081";
            sUrl = "https://idev-staff.krx.co.kr";
        } else if (severGubun == "test") {
            sUrl = "https://itest-staff.krx.co.kr";
        }
    }
    var chgList;
    var strPageURL = sUrl + "/dsclproc/JLDSTF10004.jsp?AcptNo=" + accpt_no;
    var strOptions = "width=1000, height=800, toolbar=no, location=no, menubar=no, scrollbars=yes, status=yes, resizable=yes";
    chgList = window.open(strPageURL, "공시뷰어", strOptions);
    chgList.focus();
};
/**
 * @method
 * @name openPerson
 * @description desc
 * @param {string} prn_corp_tp_cd desc
 * @param {string} birthdd desc
 * @param {string} prncorp_nm desc
 * @param {string} emp_no desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.openPerson = function(prn_corp_tp_cd, birthdd, prncorp_nm, emp_no) {
    /*
		var    _previewWindow;
		_previewWindow=window.open('', 'popup', 'width=850, height=750, toolbar=no, location=no, menubar=no, scrollbars=yes, status=yes, resizable=yes');
		//_previewWindow.opener=self;
		_previewWindow.focus();

		var f = document.personinfo;
		f.target = "popup";
		f.PRN_CORP_TP_CD.value = prn_corp_tp_cd;
		f.BIRTHDD.value = birthdd;
		f.PRNCORP_NM.value = encodeURIComponent(prncorp_nm);
		f.method.value = "personSearchList";
	    f.action = '/HindrAct.do';
		f.submit();
		*/

    var winTitle = "저해행위 인명 상세정보";
    prncorp_nm = prncorp_nm.replace('&', 'amp;');
    var url = "/HindrAct.do?method=personSearchList" + "&PRNCORP_NM=" + prncorp_nm + "&BIRTHDD=" + birthdd + "&PRN_CORP_TP_CD=" + prn_corp_tp_cd + // 인명조회
        "&EMP_NO=" + emp_no + "&SCREN_ID=JLDSTF37031.jsp" + "&SCREN_PROCES_TP_CD=1";
    $c.frame.path("/top").WinOpen("hindrPrnView" + birthdd, url, winTitle, 850, 750);
};
/**
 * @method
 * @name fn_PopupCorpChangeInfo
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_PopupCorpChangeInfo = function() {
    var chgList;
    var strPageURL = "/HindrAct.do?method=corpInfoDtl&ISUR_CD=" + gIsurCd + "&SCREN_ID=JLDSTF37032.jsp" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    var strOptions = "width=830, height=750, toolbar=no, location=no, menubar=no, scrollbars=yes, status=yes, resizable=yes";
    chgList = window.open(strPageURL, "chgList", strOptions);
    chgList.focus();
};



/******************************************************************* 
 * 함수명   : WinClose()
 * 설명     : 윈도우가 close되면 화면 index 삭제
 *******************************************************************/
/**
 * @method
 * @name WinClose
 * @description desc
 * @param {string} winid desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.WinClose = function(winid) {
    if (winid == "No name") return;
    if (winid.substring(0, 6) != "Child_") return;
    //gCloseFlag ="Y";
    //childWinCnt--;
    scwin.fn_connEndLog(gScRenLogSeq);
    $c.frame.path("/pageIndex").PageIndexDelete(winid);
};
/**
 * @method
 * @name WinClosePopup
 * @description desc
 * @param {string} winid desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.WinClosePopup = function(winid) {
    if (winid == "No name") return;
    if (winid.substring(0, 6) != "ULDSTF") return;
    scwin.fn_connEndLog(gScRenLogSeq);
};
/**
 * @method
 * @name fn_connStratLog
 * @description desc
 * @param {string} empNo desc
 * @param {string} screnId desc
 * @param {string} screnProcsTpCd desc
 * @param {string} indCond desc
 * @param {string} fileNm desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_connStratLog = function(empNo, screnId, screnProcsTpCd, indCond, fileNm) {
    trs_Log.Action = encodeURI("/HindrAct.do?method=insertHiderActConnLog" + "&INTEG_USR_ID=" + empNo + "&SCREN_ID=" + screnId + "&SCREN_PROCES_TP_CD=" + screnProcsTpCd + "&INQ_COND=" + indCond + "&ATTACH_FILE_NM=" + fileNm);
    trs_Log.KeyName = "toinb_dataid4";
    trs_Log.KeyValue = "JSP(O:pOutput=dts_Log)";
    trs_Log.Post();
};
/**
 * @method
 * @name fn_connEndLog
 * @description desc
 * @param {string} seq desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_connEndLog = function(seq) {
    if (seq == "") return;
    trs_Log.Action = encodeURI("/HindrAct.do?method=updateHiderActConnLog" + "&SEQ=" + seq);
    trs_Log.KeyName = "toinb_dataid4";
    trs_Log.KeyValue = "JSP(O:pOutput=dts_Log)";
    trs_Log.Post();
};
/**
 * @method
 * @name fn_getScRenLogSeq
 * @description desc
 * @param {string} pScrenProcsTpCd desc
 * @param {string} dtsLog desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getScRenLogSeq = function(pScrenProcsTpCd, dtsLog) {
    var str;
    if (screnProcsTpCd == '08') {
        str = gScRenLogSeq;
    } else {
        str = dtsLog.getCellData(1, "SEQ");
    }
    return str;
};
/**
 * @method
 * @name fn_condUrl
 * @description desc
 * @param {string} url desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_condUrl = function(url) {
    return encodeURI($c.ut.replaceAll(url, '&', ''));
};
/**
 * @method
 * @name fn_condUrl2
 * @description desc
 * @param {string} url desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_condUrl2 = function(url) {
    return $c.ut.replaceAll(url, '&', '');
};
